package com.jgeted.sagadyssey.social.war;
import com.jgeted.sagadyssey.social.war.api.*;
import com.jgeted.sagadyssey.social.war.domain.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class WarEngineeringRulesTest{
    static WarEngineeringJob job(){var p=new WarIntent.Position(WarKey.parse("minecraft:overworld"),1,2,3);return new WarEngineeringJob(new UUID(WarEngineeringJob.NAMESPACE,1),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),WarEngineeringJob.Mode.BUILD,Optional.of(WarKey.parse("minecraft:cobblestone")),List.of(new WarEngineeringJob.Cell(p,"air","cobblestone",20),new WarEngineeringJob.Cell(new WarIntent.Position(p.dimension(),2,2,3),"air","cobblestone",20)),WarEngineeringJob.Phase.ACTIVE,0,Set.of(),100,1,100,false,"explicit finite original work");}
    @Test void geometryIsBoundedBeforeEnumerationAndRejectsIntegerOverflow(){var d=WarKey.parse("minecraft:overworld");assertThrows(IllegalArgumentException.class,()->WarEngineeringGeometry.box(new WarIntent.Position(d,Integer.MAX_VALUE,0,0),new WarIntent.Position(d,Integer.MAX_VALUE,0,0),WarEngineeringJob.Mode.BUILD));assertThrows(IllegalArgumentException.class,()->WarEngineeringGeometry.box(new WarIntent.Position(d,0,0,0),new WarIntent.Position(d,8,0,8),WarEngineeringJob.Mode.BUILD));assertEquals(64,WarEngineeringGeometry.box(new WarIntent.Position(d,0,0,0),new WarIntent.Position(d,7,0,7),WarEngineeringJob.Mode.BUILD).size());}
    @Test void constructionBuildsBottomUpAndDiggingTopDown(){var d=WarKey.parse("minecraft:overworld");var a=new WarIntent.Position(d,0,0,0);var b=new WarIntent.Position(d,1,2,0);assertEquals(List.of(0,0,1,1,2,2),WarEngineeringGeometry.box(a,b,WarEngineeringJob.Mode.BUILD).stream().map(WarIntent.Position::y).toList());assertEquals(List.of(2,2,1,1,0,0),WarEngineeringGeometry.box(a,b,WarEngineeringJob.Mode.DIG).stream().map(WarIntent.Position::y).toList());}
    @Test void noProgressBeforeDurableIntentAndNoAdoptionOfUnknownEffects(){var j=job();assertThrows(IllegalArgumentException.class,()->j.completeCell(101,"free work"));var issuing=j.change(WarEngineeringJob.Phase.ISSUING,101,"intent before effect");assertThrows(IllegalArgumentException.class,()->issuing.adoptCell(102,"not a valid effect proof"));var done=issuing.completeCell(102,"original receipt");assertEquals(1,done.next());assertTrue(WarEngineeringJob.follows(j,issuing));assertTrue(WarEngineeringJob.follows(issuing,done));assertFalse(WarEngineeringJob.follows(j,done));}
    @Test void playerContributionDoesNotPretendToConsumeMaterialOrAdvanceWorkerSkill(){var j=job();var one=j.adoptCell(101,"actual external state approved");var two=one.adoptCell(102,"actual external state approved");assertEquals(WarEngineeringJob.Phase.DONE,two.phase());assertEquals(Set.of(0,1),two.adopted());assertTrue(WarEngineeringJob.follows(j,one));assertThrows(IllegalArgumentException.class,()->two.change(WarEngineeringJob.Phase.ACTIVE,103,"replay"));}
    @Test void interruptedWorkCanPauseAndCancelWithoutRevertingBuiltCells(){var j=job().change(WarEngineeringJob.Phase.ISSUING,101,"intent").completeCell(102,"receipt");var pause=j.change(WarEngineeringJob.Phase.PAUSED,103,"pause");var cancel=pause.change(WarEngineeringJob.Phase.CANCELLED,104,"keep first real block");assertEquals(1,cancel.next());assertTrue(WarEngineeringJob.follows(pause,cancel));assertThrows(IllegalArgumentException.class,()->cancel.change(WarEngineeringJob.Phase.ACTIVE,105,"resume cancelled"));}
    @Test void clocksAndImmutableTermsCannotBeRewritten(){var a=job();assertThrows(IllegalArgumentException.class,()->a.change(WarEngineeringJob.Phase.PAUSED,99,"old time"));var b=job().change(WarEngineeringJob.Phase.PAUSED,101,"other people");assertFalse(WarEngineeringJob.follows(a,b));var issued=a.change(WarEngineeringJob.Phase.ISSUING,101,"intent");assertTrue(WarEngineeringJob.follows(issued,issued.notApplied(102,"original rollback proves no effect")));assertTrue(WarEngineeringJob.follows(issued,issued.cancelUnissued(102,"same-session not invoked")));}
    @Test void engineeringRequiresItsOwnOriginalConsentAndNoCompulsoryStaffScale(){var r=WarMusterBookTest.offer().request();var e=new WarMilitiaRequest(r.id(),r.actorId(),r.armyId(),r.unitId(),r.characterId(),new WarLoadout(WarLoadout.Mount.FOOT,WarLoadout.Weapon.SWORD,false,false).id(),1,r.kind(),WarMilitiaRequest.Role.ENGINEER,r.wage(),r.requestedAtTick());assertTrue(WarServiceRoles.supported(e));assertTrue(WarOfficeQualification.compatible(WarStaffEntry.Role.ENGINEERING_LEAD,e.role()));assertFalse(WarOfficeQualification.compatible(WarStaffEntry.Role.CAPTAIN,e.role()));}
}
